-- Reviewer feedback pass: PRD / Product Feature / Spec triad, User Flow, SWOT, Project Charter.

update templates
set
  name = 'Product Spec',
  description = 'Hypothesis-driven growth/feature spec — use for experiments and data-backed bets (not large epics; see PRD)',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Problem & Insight"}]},{"type":"paragraph","content":[{"type":"text","text":"What problem are we solving, and what evidence validates it? Link related Insight or Problem docs via Properties → Origin.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Describe the core problem and the user insight or data that validates it.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hypothesis"}]},{"type":"paragraph","content":[{"type":"text","text":"If / then / because — keep it falsifiable. Prefer this template when the change is a testable bet.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If we "},{"type":"text","text":"[build/change this feature]","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"[this behavior will happen]","marks":[{"type":"bold"}]},{"type":"text","text":", because "},{"type":"text","text":"[underlying reasoning].","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Goals & Non-Goals"}]},{"type":"paragraph","content":[{"type":"text","text":"Be explicit about what is out of scope to prevent creep.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"In Scope:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Key deliverable 1]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Key deliverable 2]"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Out of Scope:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[What we are NOT building right now]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"User Experience & Flow"}]},{"type":"paragraph","content":[{"type":"text","text":"Walk through the journey in order. Link a User Flow Definition via Origin when the path is complex.","marks":[{"type":"italic"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Step 1 of the user journey]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Step 2 of the user journey]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Technical Architecture & Considerations"}]},{"type":"paragraph","content":[{"type":"text","text":"Data, APIs, and constraints that affect the build.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Data structure changes, API requirements, or frontend/backend constraints]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Success Metrics"}]},{"type":"paragraph","content":[{"type":"text","text":"One primary metric and one guardrail that must not degrade.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Primary Metric: [What determines success?]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guardrail Metric: [What should not degrade?]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"product_spec","category":"product","use_cases":["Growth / experiment-backed features","Hypothesis-driven specs","Falsifiable product bets"],"supported_views":["kanban","gantt","dashboard"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"priority","field_label":"Priority","field_type":"select","options":["p0","p1","p2","p3"],"ai_fill_enabled":true},{"field_key":"milestone","field_label":"Milestone","field_type":"text","ai_fill_enabled":true}],"default_properties":{"status":"draft","priority":"p2"}}'::jsonb
where slug = 'product-spec'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
set
  name = 'Product Requirements Document',
  description = 'Delivery PRD for larger core epics — MoSCoW scope and user stories (not hypothesis growth bets; see Product Spec)',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Problem Statement & Insight"}]},{"type":"paragraph","content":[{"type":"text","text":"The problem this initiative solves, and the evidence behind it. Link related Problem or Insight docs via Properties → Origin.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Problem statement and supporting insight.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"User Stories / How Might We"}]},{"type":"paragraph","content":[{"type":"text","text":"Frame from the user''s perspective. Prefer BDD-style stories: As a … I want to … so that …","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[As a ... I want to ... so that ...]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[How might we ...?]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scope & Requirements"}]},{"type":"paragraph","content":[{"type":"text","text":"Negotiate Must / Should / Could / Won''t before build. MoSCoW forces hard priority calls inside the epic.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Req ID"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Description"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"MoSCoW"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Effort"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Status"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"REQ-1"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Requirement description]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Must"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[S/M/L]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"REQ-2"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Requirement description]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Should"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[S/M/L]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Out of Scope"}]},{"type":"paragraph","content":[{"type":"text","text":"What this explicitly does not cover — prevents scope creep.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Out of scope item]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Success Metrics & KPIs"}]},{"type":"paragraph","content":[{"type":"text","text":"Even delivery epics need a readout — primary outcome plus guardrails so shipping doesn''t silently erode core metrics.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Primary KPI: [metric + target + baseline]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guardrail: [metric that must not degrade]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How we''ll measure: [source / dashboard]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"prd","category":"product","use_cases":["Core epics / initiatives","Cross-functional delivery","MoSCoW scope management"],"supported_views":["wiki","kanban","gantt"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"priority","field_label":"Priority","field_type":"select","options":["low","medium","high","critical"],"ai_fill_enabled":true},{"field_key":"strategic_alignment","field_label":"Strategic alignment","field_type":"select","options":["user_growth","retention","tech_debt","compliance"],"ai_fill_enabled":true},{"field_key":"product_area","field_label":"Product area","field_type":"select","options":["core_app","browser_extension","admin_panel","api"],"ai_fill_enabled":true},{"field_key":"target_release","field_label":"Target release","field_type":"text","ai_fill_enabled":false}],"default_properties":{"status":"draft","priority":"medium"}}'::jsonb
where slug = 'prd'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
set
  name = 'Product Feature',
  description = 'Tactical one-pager for bounded features — problem, solution, acceptance criteria (not full epics or growth hypotheses)',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Problem & Opportunity"}]},{"type":"paragraph","content":[{"type":"text","text":"What''s the gap this small, bounded feature addresses? Link related Problem or Insight docs via Properties → Origin.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Problem and opportunity.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Proposed Solution"}]},{"type":"paragraph","content":[{"type":"text","text":"What you''re building, at a level a non-engineer can follow. Note what is explicitly out of scope to stop creep.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Proposed solution.]"}]},{"type":"paragraph","content":[{"type":"text","text":"Out of scope:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[What this feature will not do]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Acceptance Criteria"}]},{"type":"paragraph","content":[{"type":"text","text":"Testable done-conditions. Prefer Given / When / Then so eng and QA share one definition of done.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Given ... when ... then ...]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Given ... when ... then ...]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Success Metrics"}]},{"type":"paragraph","content":[{"type":"text","text":"How you''ll validate after ship — avoid silent long-term metric erosion.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Metric and target]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"product_feature","category":"product","use_cases":["Tactical feature one-pagers","Sprint backlog items","Bounded delivery tickets"],"supported_views":["kanban","wiki","gantt"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"feature_status","field_label":"Feature status","field_type":"status","options":[{"value":"idea","label":"Idea","category":"unstarted"},{"value":"planned","label":"Planned","category":"unstarted"},{"value":"building","label":"Building","category":"started"},{"value":"shipped","label":"Shipped","category":"completed"},{"value":"deprecated","label":"Deprecated","category":"canceled"}],"ai_fill_enabled":true},{"field_key":"product_area","field_label":"Product area","field_type":"select","options":["core_app","browser_extension","admin_panel","api"],"ai_fill_enabled":true},{"field_key":"target_release","field_label":"Target release","field_type":"text","ai_fill_enabled":false}],"default_properties":{"status":"draft","feature_status":"idea"}}'::jsonb
where slug = 'product-feature'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
set
  name = 'User Flow Definition',
  description = 'Goal, happy path, decisions, edge cases, and success state for one user task',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"User & Goal"}]},{"type":"paragraph","content":[{"type":"text","text":"Who is this for and what single task are they completing? Set Product / Market / Audience / Surface in Properties → Targeting (Audience = persona/segment).","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Persona or role + goal in one sentence.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Entry Point"}]},{"type":"paragraph","content":[{"type":"text","text":"How the user arrives — URL, CTA, notification, deep link, or prior flow.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Entry point and trigger.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Happy Path"}]},{"type":"paragraph","content":[{"type":"text","text":"Ordered screens and actions from entry to success. One goal per flow. Include a link to the Figma / FigJam canvas here.","marks":[{"type":"italic"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Screen / action 1]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Screen / action 2]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Screen / action 3]"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Figma / FigJam link:]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Decision Points"}]},{"type":"paragraph","content":[{"type":"text","text":"Branches that change the path (auth, permissions, empty states, pricing tiers).","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Decision] — Yes → [path] / No → [path]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edge Cases & Error States"}]},{"type":"paragraph","content":[{"type":"text","text":"Empty states, validation errors, offline, permissions — flows fail here more often than on the happy path. No dead ends.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Edge case] — [System response / recovery]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Success State"}]},{"type":"paragraph","content":[{"type":"text","text":"What the user sees once the flow completes. Note the analytics event that fires when the goal is reached.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Success state + confirmation / next CTA.]"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Analytics event: [event name / properties]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Handoff Notes"}]},{"type":"paragraph","content":[{"type":"text","text":"Data passed between steps and open product/eng questions.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Event or data note]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Open question]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"user_flow_definition","category":"product","use_cases":["UX flows","Interaction design","Feature handoff to engineering"],"supported_views":["wiki","kanban"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"flow_status","field_label":"Flow status","field_type":"status","options":[{"value":"draft","label":"Draft","category":"unstarted"},{"value":"in_review","label":"In review","category":"started"},{"value":"approved","label":"Approved","category":"completed"}],"ai_fill_enabled":true},{"field_key":"product_area","field_label":"Product area","field_type":"select","options":["core_app","browser_extension","admin_panel","api"],"ai_fill_enabled":true},{"field_key":"target_release","field_label":"Target release","field_type":"text","ai_fill_enabled":false}],"schema_groups":[{"group_key":"targeting","group_label":"Targeting","repeatable":false,"fields":[{"sub_key":"product","field_label":"Product","field_type":"text","ai_fill_enabled":true},{"sub_key":"market","field_label":"Market","field_type":"text","ai_fill_enabled":true},{"sub_key":"audience","field_label":"Audience","field_type":"text","ai_fill_enabled":true},{"sub_key":"surface","field_label":"Surface","field_type":"text","ai_fill_enabled":true}]}],"default_properties":{"status":"draft","flow_status":"draft"}}'::jsonb
where slug = 'user-flow-definition'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
set
  name = 'SWOT Analysis',
  description = 'Scoped SWOT with strategic implications — living strategy context for PRDs, insights, and ADRs',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Strengths"}]},{"type":"paragraph","content":[{"type":"text","text":"Internal advantages. Keep each item as a short bullet — no prose paragraphs.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Strength]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weaknesses"}]},{"type":"paragraph","content":[{"type":"text","text":"Internal gaps or limitations. Short bullets only.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Weakness]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Opportunities"}]},{"type":"paragraph","content":[{"type":"text","text":"External factors you could capitalize on. Short bullets only.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Opportunity]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Threats"}]},{"type":"paragraph","content":[{"type":"text","text":"External factors that could work against you. Short bullets only.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Threat]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Strategic Implications / Action Items"}]},{"type":"paragraph","content":[{"type":"text","text":"The ''so what'' — how strengths unlock opportunities, and how you protect weaknesses against threats (TOWS). Prefer concrete next docs or experiments.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SO: [Use strength X to capture opportunity Y]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ST / WO / WT: [Mitigation or follow-up]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Next: [Insight / Problem / PRD to open]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"swot_analysis","category":"product","use_cases":["Strategic planning","Competitive analysis","Business reviews"],"supported_views":["wiki","dashboard"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"analysis_scope","field_label":"Analysis scope","field_type":"text","ai_fill_enabled":true},{"field_key":"competitor_name","field_label":"Competitor","field_type":"text","ai_fill_enabled":true},{"field_key":"last_audited","field_label":"Last audited","field_type":"date","ai_fill_enabled":true},{"field_key":"valid_until","field_label":"Valid until","field_type":"date","ai_fill_enabled":false}],"default_properties":{"status":"draft"}}'::jsonb
where slug = 'swot-analysis'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
set
  name = 'Project Charter',
  description = 'Executive buy-in charter — objective, scope, sponsor, risks, and milestones for a cross-functional initiative',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Objective & Business Case"}]},{"type":"paragraph","content":[{"type":"text","text":"What the project is, and why the business value justifies the investment.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Objective.]"}]},{"type":"paragraph","content":[{"type":"text","text":"[Business case / value.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scope"}]},{"type":"paragraph","content":[{"type":"text","text":"Must include what is strictly OUT of scope. Ambiguity here becomes budget and timeline risk later.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In scope: [item]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Out of scope: [item]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Stakeholders & Roles"}]},{"type":"paragraph","content":[{"type":"text","text":"Who''s involved, and what they''re responsible for. Sponsor lives in Properties.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Name/Role] — [Responsibility]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Key Risks & Constraints"}]},{"type":"paragraph","content":[{"type":"text","text":"Surface material risks and hard constraints on day one — resources, deadlines, compliance — so you aren''t measured against surprises later.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Risk or constraint] — [Mitigation / owner]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Milestones"}]},{"type":"paragraph","content":[{"type":"text","text":"Keep as a clean table (Phase | Date | Deliverable) so it can feed Gantt / task tools later.","marks":[{"type":"italic"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Phase"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Target date"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Deliverable"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Owner"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Phase]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Date]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Deliverable]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Owner]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Success Criteria"}]},{"type":"paragraph","content":[{"type":"text","text":"How you''ll know this project succeeded — outcomes, not activity.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Success criterion]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"project_charter","category":"marketing","use_cases":["Project kickoff","Cross-functional initiatives","Stakeholder alignment"],"supported_views":["wiki","gantt","kanban"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"project_timeframe","field_label":"Project timeframe","field_type":"date_range","ai_fill_enabled":true},{"field_key":"target_launch","field_label":"Target launch","field_type":"date","ai_fill_enabled":true},{"field_key":"sponsor","field_label":"Sponsor","field_type":"text","ai_fill_enabled":true}],"default_properties":{"status":"draft"}}'::jsonb
where slug = 'project-charter'
  and coalesce(is_system, false) = true
  and workspace_id is null;

insert into metadata_schemas (workspace_id, field_key, field_label, field_type, options, ai_fill_enabled)
select ms.workspace_id, v.field_key, v.field_label, v.field_type, v.options, v.ai_fill_enabled
from (
  select distinct workspace_id from metadata_schemas where field_key in ('analysis_scope', 'sponsor', 'product_area')
) ms
cross join (
  values
    ('competitor_name', 'Competitor', 'text', null::jsonb, true),
    ('valid_until', 'Valid until', 'date', null::jsonb, false),
    ('project_timeframe', 'Project timeframe', 'date_range', null::jsonb, true),
    ('target_launch', 'Target launch', 'date', null::jsonb, true)
) as v(field_key, field_label, field_type, options, ai_fill_enabled)
where not exists (
  select 1 from metadata_schemas e
  where e.workspace_id = ms.workspace_id and e.field_key = v.field_key
);
